import type { Metadata, MetadataRoute } from 'next';
import { faviconAsset, iconSizes } from './brand';
import type { MediaRef } from './schemas/common';

// Favicon / app-icon wiring (WS-E). Pure: the layout, the manifest and
// /icon.png all read these, so the tags, the manifest and the files agree.
//
// Bundled set (public/brand-default, generated by scripts/generate-brand-icons.mjs):
// the ring-with-three-dots symbol only, never the full wordmark. An owner
// upload (Settings -> Brand) overrides the whole set when it is usable.

/** Google needs a favicon of at least 48x48 (a multiple of 48 is best); anything smaller is ignored here. */
export const MIN_FAVICON_PX = 48;

export const BUNDLED_ICONS = {
  svg: '/brand-default/icon.svg',
  ico: '/favicon.ico',
  png32: '/brand-default/icon-32.png',
  png48: '/brand-default/icon-48.png',
  apple180: '/brand-default/icon-180.png',
  png192: '/brand-default/icon-192.png',
  png512: '/brand-default/icon-512.png',
  maskable512: '/brand-default/icon-maskable-512.png',
} as const;

/** Declared pixel size of every bundled PNG (checked against the files in icons.test.ts). */
export const BUNDLED_ICON_SIZES: Record<string, number> = {
  [BUNDLED_ICONS.png32]: 32,
  [BUNDLED_ICONS.png48]: 48,
  [BUNDLED_ICONS.apple180]: 180,
  [BUNDLED_ICONS.png192]: 192,
  [BUNDLED_ICONS.png512]: 512,
  [BUNDLED_ICONS.maskable512]: 512,
};

/** The owner's uploaded favicon when it is big enough to serve, else undefined (bundled symbol applies). */
export function usableFavicon(fav: MediaRef | undefined): MediaRef | undefined {
  if (!fav) return undefined;
  const a = faviconAsset(fav);
  return Math.min(a.width, a.height) >= MIN_FAVICON_PX ? fav : undefined;
}

/** `metadata.icons` for the root layout. */
export function iconMetadata(fav: MediaRef | undefined): NonNullable<Metadata['icons']> {
  if (usableFavicon(fav)) return { icon: '/icon.png', apple: '/icon.png' };
  return {
    icon: [
      { url: BUNDLED_ICONS.ico, sizes: '16x16 32x32 48x48' },
      { url: BUNDLED_ICONS.svg, type: 'image/svg+xml' },
      { url: BUNDLED_ICONS.png48, sizes: '48x48', type: 'image/png' },
      { url: BUNDLED_ICONS.png192, sizes: '192x192', type: 'image/png' },
    ],
    apple: [{ url: BUNDLED_ICONS.apple180, sizes: '180x180', type: 'image/png' }],
  };
}

type ManifestIcon = NonNullable<MetadataRoute.Manifest['icons']>[number];

/** Web-app-manifest icons; declared sizes always match the served files. */
export function manifestIcons(fav: MediaRef | undefined): ManifestIcon[] {
  const up = usableFavicon(fav);
  if (up) {
    const a = faviconAsset(up);
    return [{ src: '/icon.png', sizes: iconSizes(a), type: a.type, purpose: 'any' }];
  }
  return [
    { src: BUNDLED_ICONS.png192, sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: BUNDLED_ICONS.png512, sizes: '512x512', type: 'image/png', purpose: 'any' },
    // Ring kept inside the centred 80% safe zone so Android's mask never clips it.
    { src: BUNDLED_ICONS.maskable512, sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ];
}
